export function buildLine(mats, { workers = true, flow = true, floorLabels = true, lang = 'zh', zones = true } = {}) {
  const root = new THREE.Group();
  const t = mats.t;

  // ---------- floor ----------
  const floor = new THREE.Mesh(new THREE.PlaneGeometry(400, 400), mats.floor);
  floor.rotation.x = -Math.PI / 2;
  floor.position.set(L / 2, 0, W / 2);
  floor.receiveShadow = true;
  root.add(floor);

  // zone pads (very subtle tint) + outline
  if (t.dark) {
    // engineering grid (1 m minor, 5 m major)
    const minor = [], major = [];
    for (let x = -10; x <= 65; x += 1) (x % 5 ? minor : major).push(new THREE.Vector3(x, 0.002, -6), new THREE.Vector3(x, 0.002, 16…
    for (let z = -6; z <= 16; z += 1) (z % 5 ? minor : major).push(new THREE.Vector3(-10, 0.002, z), new THREE.Vector3(65, 0.002, z…
    root.add(new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(minor), new THREE.LineBasicMaterial({ color: 0x121a20 …
    root.add(new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(major), new THREE.LineBasicMaterial({ color: 0x1b262e …
  }
  if (zones) {
    const zoneDefs = [
      { k: 'cell', x0: 0, x1: 12.6, z0: 0.3, z1: 8.2 },
      { k: 'module', x0: 12.6, x1: 36.2, z0: 0.0, z1: 4.4 },
      { k: 'pack', x0: 21.6, x1: 55, z0: 4.6, z1: 9.0 },
    ];
    for (const z of zoneDefs) {
      const pad = new THREE.Mesh(
        new THREE.PlaneGeometry(z.x1 - z.x0, z.z1 - z.z0),
        new THREE.MeshBasicMaterial({ color: t.zone[z.k], transparent: true, opacity: t.dark ? 0.018 : 0.045, depthWrite: false }),
      );
      pad.rotation.x = -Math.PI / 2;
      pad.position.set((z.x0 + z.x1) / 2, 0.003, (z.z0 + z.z1) / 2);
      root.add(pad);
      const pts = [[z.x0, z.z0], [z.x1, z.z0], [z.x1, z.z1], [z.x0, z.z1], [z.x0, z.z0]].map(([x, zz]) => new THREE.Vector3(x, 0.00…
      const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), new THREE.LineBasicMaterial({ color: t.zone[z.k], …
      root.add(line);
    }
    // walkway safety lines
    const stripe = new THREE.MeshBasicMaterial({ color: t.floorLine });
    for (const [x0, x1, z] of [[0, 55, 9.6], [12.6, 55, 4.5], [0, 55, -0.5]]) {
      const s = new THREE.Mesh(new THREE.PlaneGeometry(x1 - x0, 0.08), stripe);
      s.rotation.x = -Math.PI / 2;
      s.position.set((x0 + x1) / 2, 0.004, z);
      root.add(s);
    }
  }

  // 0 — 55 m dimension line along the front edge
  if (floorLabels) {
    const dimMat = new THREE.LineBasicMaterial({ color: t.dark ? 0x4a5660 : 0x8f989d });
    const zf = 10.3;
    const pts = [new THREE.Vector3(0, 0.01, zf), new THREE.Vector3(L, 0.01, zf)];
    for (let x = 0; x <= L; x += 5) pts.push(new THREE.Vector3(x, 0.01, zf - (x % 10 ? 0.12 : 0.25)), new THREE.Vector3(x, 0.01, zf…
    pts.push(new THREE.Vector3(L, 0.01, zf - 0.25), new THREE.Vector3(L, 0.01, zf + 0.25));
    root.add(new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(pts), dimMat));
    for (const x of [0, 10, 20, 30, 40, 50]) {
      const ft = floorText(String(x), { size: 0.36, color: t.dark ? '#5a6670' : '#8e978d', font: '500 120px "JetBrains Mono", monos…
      ft.position.set(x + 0.12, 0.01, zf + 0.75);
      root.add(ft);
    }
    const end = floorText('55 m', { size: 0.42, color: t.dark ? '#8cff5c' : '#2f7d1e', font: '700 120px "JetBrains Mono", monospace…
    end.position.set(L + 0.2, 0.01, zf + 0.78);
    root.add(end);
  }

  if (floorLabels) {
    const lab = lang === 'zh'
      ? [['01  电芯处理段', 0.4, 8.0], ['02  模组堆叠焊接段', 12.9, 0.05], ['03  PACK 装配测试段', 22.0, 8.9]]
      : [['01  CELL PROCESSING', 0.4, 8.0], ['02  MODULE STACKING & WELDING', 12.9, 0.05], ['03  PACK ASSEMBLY & TEST', 22.0, 8.9]];
    for (const [s, x, z] of lab) {
      const ft = floorText(s, { size: 0.42, color: t.dark ? '#5a6670' : '#8e978d' });
      ft.position.set(x, 0.008, z - 0.25);
      root.add(ft);
    }
  }

  // ---------- 01–06 cell processing ----------
  const cellZone = new THREE.Group();
  root.add(cellZone);
  cellZone.add(at(fence(mats, { w: 5.4, d: 6.2, openings: [104, 0] }), 2.9, 0, 5.0));
  // incoming full pallets (blue cells) + outgoing empty foam trays
