    const cb = cellBlock(mats, { nx: 13, ny: 4, nz: 5 });
    cb.position.set(-0.52, 0.14, -0.48);
    pallet.add(cb);
    pallet.position.set(1.2, 0, z);
    cellZone.add(pallet);
  }
  const foam = mesh(rbox(1.1, 0.9, 1.1, 0.03), mats.body, 3.6, 0.45 + 0.14, 7.4);
  cellZone.add(foam);
  cellZone.add(mesh(new THREE.BoxGeometry(1.15, 0.14, 1.15), mats.plinth, 3.6, 0.07, 7.4));
  const bot = robot(mats, { scale: 0.92, pose: [Math.PI * 0.86, -0.5, -0.35, -0.35] });
  bot.position.set(3.2, 0, 5.0);
  cellZone.add(bot);
  // control cabinet
  cellZone.add(at(machine(mats, { w: 0.9, d: 0.6, h: 1.9, windows: 1, tower: false }), 5.0, 0, 2.3));
  // accumulation conveyor → tester
  const acc = conveyor(mats, { len: 3.0, w: 0.5, type: 'belt' });
  acc.position.set(5.6, 0, 4.6);
  cellZone.add(acc);
  const tester = machine(mats, { w: 2.6, d: 1.9, h: 2.0, windows: 2 });
  tester.position.set(9.3, 0, 4.6);
  cellZone.add(tester);
  // flip & split towards the two stacking stations
