const V = (x, y, z) => new THREE.Vector3(x, y, z);

// Camera keyframes: p = scroll progress where the shot is reached.
const KEYS = [
  { p: 0.0, pos: V(-16.0, 27.0, 40.0), tgt: V(22, -2, 3) },
  { p: 0.1, pos: V(-8.2, 13.8, 21.9), tgt: V(3.4, 1.0, 5.0) },
  { p: 0.18, pos: V(-0.3, 10.6, 18.3), tgt: V(9.4, 1.0, 4.6) },
  { p: 0.26, pos: V(4.2, 10.8, 16.3), tgt: V(11.8, 0.8, 2.6) },
  { p: 0.34, pos: V(6.4, 11.0, 15.4), tgt: V(14.6, 1.0, 2.5) },
  { p: 0.42, pos: V(9.9, 10.4, 15.4), tgt: V(18.2, 1.2, 2.5) },
  { p: 0.52, pos: V(16.5, 10.4, 15.4), tgt: V(25.6, 1.2, 2.5) },
  { p: 0.6, pos: V(21.7, 10.4, 15.4), tgt: V(30.4, 1.2, 2.5) },
  { p: 0.66, pos: V(25.9, 14.2, 18.3), tgt: V(34.2, 2.0, 4.5) },
  { p: 0.72, pos: V(48.1, 13.8, 24.3), tgt: V(25.8, 1.0, 6.6) },
  { p: 0.78, pos: V(41.9, 12.3, 23.2), tgt: V(30.0, 1.2, 6.6) },
  { p: 0.83, pos: V(40.9, 12.0, 22.2), tgt: V(34.0, 1.2, 6.6) },
  { p: 0.88, pos: V(34.0, 12.3, 23.6), tgt: V(44.0, 1.0, 6.6) },
  { p: 0.94, pos: V(41.1, 13.4, 25.0), tgt: V(53.0, 1.0, 5.8) },
  { p: 1.0, pos: V(74.0, 27.0, 40.0), tgt: V(30, -2, 3) },
];

// Scroll progress at which each station is in focus.
export const STATION_P = {
  '01': 0.08, '02': 0.1, '03': 0.16, '04': 0.19, '05': 0.24, '06': 0.27, '07': 0.34, '08': 0.41, '09': 0.45, '10': 0.5,
  '11': 0.54, '12': 0.58, '13': 0.61, '14': 0.66, '15': 0.7, '16': 0.73, '17': 0.78, '18': 0.83, '19': 0.88, '20': 0.93, '21': 0.96,
};

const smooth = (t) => t * t * (3 - 2 * t);
const PORTRAIT_WIDE = { pos: V(-15, 19, 17), tgt: V(22, -2, 4.5) };

export function mountJourney({ canvas, lang, onStation, onReady, portrait }) {
  const quality = pickQuality();
  const theme = THEMES.light;
  const mats = makeMaterials(theme);
  const stage = createStage(canvas, { theme, fov: 24, ao: quality.ao, bloom: quality.bloom ? 0.55 : 0, pixelRatio: quality.dpr, sun…
  const { root, path, housingPath } = buildLine(mats, { lang });
  stage.scene.add(root);

  const posCurve = new THREE.CatmullRomCurve3(KEYS.map((k) => k.pos), false, 'centripetal');
  const tgtCurve = new THREE.CatmullRomCurve3(KEYS.map((k) => k.tgt), false, 'centripetal');
  const n = KEYS.length - 1;

  // Map each station to a head position (u) on the energy path.
  const curve = path.userData.curve;
  const samples = Array.from({ length: 400 }, (_, i) => curve.getPointAt(i / 399));
  const nearestU = ([x, , z]) => {
    let best = 0, bd = Infinity;
    samples.forEach((s, i) => { const d = (s.x - x) ** 2 + (s.z - z) ** 2; if (d < bd) { bd = d; best = i; } });
    return best / 399;
  };
  const stationU = {};
  for (const no of Object.keys(STATION_P)) stationU[no] = ['15', '16', '17'].includes(no) ? null : nearestU(anchors[no]);
  stationU['15'] = stationU['16'] = stationU['17'] = stationU['14'];
  const headKeys = Object.keys(STATION_P).map((no) => [STATION_P[no], stationU[no]]);
  headKeys.unshift([0, 0.0]);
  headKeys.push([1, 1]);
  const headAt = (p) => {
    for (let i = 1; i < headKeys.length; i++) {
      const [p0, u0] = headKeys[i - 1], [p1, u1] = headKeys[i];
      if (p <= p1) return u0 + (u1 - u0) * smooth((p - p0) / (p1 - p0 || 1));
    }
    return 1;
  };

  let progress = 0, target = 0, active = null, running = true, visible = true, dirty = true;
  const camPos = new THREE.Vector3(), camTgt = new THREE.Vector3();
  const portraitShift = () => (portrait() ? 0.2 : 0);

  function apply(p) {
    // piecewise: find segment, ease inside it
    let i = 0;
    while (i < n - 1 && p > KEYS[i + 1].p) i++;
    const local = smooth(Math.min(1, Math.max(0, (p - KEYS[i].p) / (KEYS[i + 1].p - KEYS[i].p))));
    const u = (i + local) / n;
    posCurve.getPoint(u, camPos);
    tgtCurve.getPoint(u, camTgt);
    if (portrait()) {
      camPos.sub(camTgt).multiplyScalar(1.4).add(camTgt);
      // ends of the journey: a steeper, wider establishing shot that fits the whole line on a tall screen
      const ends = Math.max(0, 1 - p / 0.1, (p - 0.9) / 0.1);
      if (ends > 0) { camPos.lerp(PORTRAIT_WIDE.pos, smooth(Math.min(1, ends))); camTgt.lerp(PORTRAIT_WIDE.tgt, smooth(Math.min(1, …
    }
    stage.camera.position.copy(camPos);
