export const CELL = { h: 0.207, w: 0.173, t: 0.072 }; // metres (H × W × T)

export function productMaterials(t) {
  return {
    wrap: new THREE.MeshPhysicalMaterial({ color: 0x1f3fa6, roughness: 0.38, metalness: 0.0, clearcoat: 0.6, clearcoatRoughness: 0.…
    can: new THREE.MeshStandardMaterial({ color: 0xc9ced3, roughness: 0.28, metalness: 0.85 }),
    terminalAl: new THREE.MeshStandardMaterial({ color: 0xd9dde0, roughness: 0.22, metalness: 0.95 }),
    terminalCu: new THREE.MeshStandardMaterial({ color: 0xc98a5a, roughness: 0.3, metalness: 0.9 }),
    vent: new THREE.MeshStandardMaterial({ color: 0x9aa2a8, roughness: 0.5, metalness: 0.6 }),
    endplate: new THREE.MeshStandardMaterial({ color: 0xb9bfc4, roughness: 0.42, metalness: 0.7 }),
    strap: new THREE.MeshStandardMaterial({ color: 0x23282d, roughness: 0.35, metalness: 0.8 }),
    ccs: new THREE.MeshPhysicalMaterial({ color: 0xf2f3f0, roughness: 0.55, transmission: 0.0, metalness: 0 }),
    busbar: new THREE.MeshStandardMaterial({ color: 0xd8c3a5, roughness: 0.25, metalness: 0.95 }),
    weld: new THREE.MeshBasicMaterial({ color: t?.glow ?? 0x86f25a, toneMapped: false }),
    label: new THREE.MeshStandardMaterial({ color: 0xf4f5f2, roughness: 0.6 }),
    shadow: new THREE.ShadowMaterial({ opacity: 0.16 }),
  };
}

/** A single 314 Ah prismatic LFP cell. Origin at the bottom centre. */
export function buildCell(pm, { scale = 1, terminals = true } = {}) {
  const g = new THREE.Group();
  const { h, w, t } = CELL;
  const body = new THREE.Mesh(new RoundedBoxGeometry(t, h - 0.008, w, 3, 0.004), pm.wrap);
  body.position.y = (h - 0.008) / 2;
  body.castShadow = body.receiveShadow = true;
  g.add(body);
  const cap = new THREE.Mesh(new RoundedBoxGeometry(t * 0.985, 0.01, w * 0.985, 2, 0.003), pm.can);
  cap.position.y = h - 0.005;
  cap.castShadow = true;
  g.add(cap);
  if (terminals) {
    for (const [z, mat] of [[-w * 0.3, pm.terminalAl], [w * 0.3, pm.terminalCu]]) {
      const base = new THREE.Mesh(new RoundedBoxGeometry(t * 0.62, 0.006, 0.04, 2, 0.002), pm.vent);
      base.position.set(0, h + 0.003, z);
      g.add(base);
      const post = new THREE.Mesh(new RoundedBoxGeometry(t * 0.5, 0.008, 0.032, 2, 0.002), mat);
      post.position.set(0, h + 0.009, z);
      post.castShadow = true;
      g.add(post);
    }
    const vent = new THREE.Mesh(new THREE.CylinderGeometry(0.012, 0.012, 0.002, 24), pm.vent);
    vent.scale.set(1, 1, 1.8);
    vent.position.set(0, h + 0.001, 0);
    g.add(vent);
  }
  // barcode label on the broad face
  const lab = new THREE.Mesh(new THREE.PlaneGeometry(0.03, 0.05), pm.label);
  lab.rotation.y = Math.PI / 2;
  lab.position.set(t / 2 + 0.0006, h * 0.72, w * 0.25);
  g.add(lab);
  g.scale.setScalar(scale);
  return g;
}

/**
 * 1P13S module. explode ∈ [0,1]: 0 = assembled, 1 = fully exploded.
 * Returns { group, parts, weldPoints(world anchors) }.
 */
export function buildModule(pm, { n = 13, explode = 0 } = {}) {
  const group = new THREE.Group();
  const { h, w, t } = CELL;
  const gap = 0.0015 + explode * 0.03;
  const total = n * t + (n - 1) * gap;
  const cells = [];
  for (let i = 0; i < n; i++) {
    const c = buildCell(pm);
    c.position.x = -total / 2 + t / 2 + i * (t + gap);
    // alternate polarity so the busbars zig-zag (series)
    if (i % 2) c.rotation.y = Math.PI;
    group.add(c);
    cells.push(c);
  }
  // end plates
  const epT = 0.022;
  const epGeo = new RoundedBoxGeometry(epT, h * 0.98, w * 1.04, 3, 0.004);
  const endPlates = [-1, 1].map((s) => {
    const ep = new THREE.Mesh(epGeo, pm.endplate);
    ep.position.set(s * (total / 2 + epT / 2 + 0.002 + explode * 0.16), h * 0.49, 0);
    ep.castShadow = ep.receiveShadow = true;
    // ribs
    for (const y of [-0.06, 0, 0.06]) {
      const rib = new THREE.Mesh(new THREE.BoxGeometry(0.008, 0.012, w * 0.9), pm.endplate);
      rib.position.set(s * 0.013, y, 0);
      ep.add(rib);
    }
    group.add(ep);
    return ep;
  });
  // steel straps (two loops)
  const strapLen = total + 2 * epT + 0.01;
  const straps = [0.055, 0.15].map((y, k) => {
    const sg = new THREE.Group();
    const thick = 0.0016, hgt = 0.022;
    const lift = explode * (0.11 + k * 0.05);
    for (const z of [-w / 2 - 0.006 - explode * 0.05, w / 2 + 0.006 + explode * 0.05]) {
      const s = new THREE.Mesh(new THREE.BoxGeometry(strapLen, hgt, thick), pm.strap);
      s.position.set(0, 0, z);
      s.castShadow = true;
      sg.add(s);
    }
    for (const x of [-strapLen / 2 - explode * 0.16, strapLen / 2 + explode * 0.16]) {
      const s = new THREE.Mesh(new THREE.BoxGeometry(thick, hgt, w + 0.012 + explode * 0.1), pm.strap);
      s.position.set(x, 0, 0);
      sg.add(s);
    }
    sg.position.y = y + lift * 0.25;
    group.add(sg);
    return sg;
  });
  // CCS carrier + busbars + weld points
  const ccs = new THREE.Group();
  const ccsY = h + 0.016 + explode * 0.2;
  ccs.position.y = ccsY;
  const carrier = new THREE.Mesh(new RoundedBoxGeometry(total + 0.01, 0.006, w * 0.42, 2, 0.002), pm.ccs);
  carrier.castShadow = true;
  ccs.add(carrier);
  const weldPoints = [];
  const busW = 0.034, busT = 0.003;
  for (const side of [-1, 1]) {
    const zz = side * w * 0.3;
    // series pairs: (0,1) (2,3)... on one side, (1,2) (3,4)... on the other
    const start = side < 0 ? 0 : 1;
    for (let i = start; i < n - 1; i += 2) {
      const x0 = cells[i].position.x, x1 = cells[i + 1].position.x;
      const bar = new THREE.Mesh(new RoundedBoxGeometry(x1 - x0 + t * 0.55, busT, busW, 2, 0.001), pm.busbar);
      bar.position.set((x0 + x1) / 2, 0.005, zz);
      bar.castShadow = true;
      ccs.add(bar);
      for (const x of [x0, x1]) {
        const wp = new THREE.Mesh(new THREE.CylinderGeometry(0.0055, 0.0055, 0.0012, 16), pm.weld);
        wp.position.set(x, 0.0072, zz);
        ccs.add(wp);
        weldPoints.push(wp);
      }
    }
    // terminal output busbars at the module ends
    const endX = side < 0 ? cells[n - 1].position.x : cells[0].position.x;
    const out = new THREE.Mesh(new RoundedBoxGeometry(t * 0.9, busT * 1.6, busW * 1.2, 2, 0.001), pm.busbar);
    out.position.set(endX + (side < 0 ? 0.03 : -0.03), 0.006, zz);

